}
.wkit-fscreen-main-logo .mnu-main-link,
.wkit-fscreen-main-logo .mnu-opened {
  text-decoration: none;
  font-size: 60px;
  gap: 5px;
  overflow: hidden;
}
.wkit-fscreen-main-logo .mnu-main-link .tp-title-icon svg {
  width: 60px;
