}
.wkit-fullscreen-menu-toggle {
  position: relative;
  display: flex;
  gap: 10px;
  right: 0;
  width: 132px;
  height: 48px;
  background-color: #0f0f0f;
  border-radius: 8em;
  transform-origin: right;
  cursor: pointer;
  flex-direction: row;
  align-items: center;
  transition: 0.3s linear;
}

.wkit-fullscreen-menu-toggle.opened {
  background-color: #fff;
}

.wkit-fscreen-header .wkit-fullscreen-menu-toggle.opened {
  right: 0;
}
.wkit-fscreen-header:has(.wkit-fullscreen-menu-toggle.opened)
  .wkit-fscreen-main-logo {
  transition: background 0.5s linear;
}

.w-fscreen-menu-copy {
  color: #fff;
  position: relative;
  left: 17px;
  transition: 0.5s linear;
}

.w-fscreen-menu-copy p {
  font-weight: 500;
  font-size: 24px;
  margin: 0;
  padding: 0;
  transition: 0.5s linear;
}
.wkit-fullscreen-menu-toggle.opened .w-fscreen-menu-copy p{
    color: #000;
}
.wkit-fullscreen-menu-toggle:hover .w-fscreen-menu-copy {
  left: 12px;
}

.wkit-fullscreen-menu-main
  .wkit-fscreen-header:has(.wkit-fullscreen-menu-toggle.opened) {
  background-color: unset;
  background-image: unset;
  border: unset;
  box-shadow: unset;
  position: fixed;
  z-index: 999;
}

.wkit-fullscreen-menu-main
  .wkit-fscreen-header.relative:has(.wkit-fullscreen-menu-toggle.opened) {
  top: 40px;
  transform: translateY(-20px);
}
.wkit-fullscreen-menu-main
  .wkit-fscreen-header.relative:has(.wkit-fullscreen-menu-toggle.closed) {
  transform: translateY(0px);
}
.wkit-menu-toggle-icon {
  position: absolute;
  display: flex;
  right: 0;
  width: 60px;
  height: 60px;
  border-radius: 100%;
  clip-path: circle(25% at 50% 50%);
  background-color: #040483;
  transition: all 0.5s cubic-bezier(0.075, 0.82, 0.165, 1),
    clip-path 0.3s ease-in-out, transform 0.3s ease-in-out;
  overflow: hidden;
  justify-content: center;
  align-items: center;
}

.wkit-fullscreen-menu-toggle:hover .wkit-menu-toggle-icon {
  clip-path: circle(35% at 50% 50%);
}
.wkit-fullscreen-menu-toggle:hover .w-fscreen-menu-bar {
  scale: 1.2;
}
.wkit-fscreen-hamburger {
  position: absolute;
  width: 30px;
  height: 30px;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 1s cubic-bezier(0.075, 0.82, 0.1645, 1);
}

.w-fscreen-menu-bar {
  position: absolute;
  width: 15px;
  height: 1.5px;
  background-color: #ccc;
  transition-property: transform;
  transition: all 250ms ease-out;
}

.w-fscreen-menu-bar[data-position="top"] {
  transform: translateY(-4px);
}

.w-fscreen-menu-bar[data-position="bottom"] {
  transform: translateY(4px);
}
.wkit-fullscreen-menu-toggle.opened .w-fscreen-menu-copy {
  color: #000;
}
.wkit-fullscreen-menu-toggle.opened .w-fscreen-menu-bar[data-position="top"] {
  transform: translateY(0) rotate(45deg) scaleX(1.05);
}

.wkit-fullscreen-menu-toggle.opened
  .w-fscreen-menu-bar[data-position="middle"] {
  display: none;
}
.wkit-fullscreen-menu-toggle.opened
  .w-fscreen-menu-bar[data-position="bottom"] {
  transform: translateY(0) rotate(-45deg) scaleX(1.05);
}
.w-fscreen-menu,
.w-fscreen-menu * {
  pointer-events: auto;
}

.w-fscreen-menu {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: #0f0f0f;
