  color: #fff;
  font-size: 80px;
  font-weight: 300;
  line-height: 125%;
  transition: 0.3s linear;
  position: relative;
}

.fscreen-link::after {
    position: absolute;
    display: block;
    bottom: -6px;
    left: 0;
    width: 100%;
    -webkit-transform: scaleX(0);
    transform: scaleX(0);
    border-top: 0px solid #fff;
    content: '';
    padding-bottom: inherit;
    bottom: -2px;
    transform-origin: right;
    transition: transform 0.3s cubic-bezier(0.25,0,0.4,1), border-color 0.35s cubic-bezier(0.52,0.01,0.16,1);
}
.fscreen-link:hover::after {
    backface-visibility: hidden;
    -webkit-transform: scaleX(1);
    transform: scaleX(1);
    transform-origin: left;
}

@keyframes run-border {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(0%);
  }
}
.fscreen-link::before {
  will-change: transform;
}
.fscreen-link:hover::before {
  animation: run-border 0.6s forwards;
}
.fscreen-link:not(:hover)::before {
  animation: run-out 0.6s forwards;
}

@keyframes run-out {
  0% {
    transform: translateX(0%);
  }
  100% {
    transform: translateX(100%);
  }
}

